"""Private POSIX resource-limited Poppler launcher. No visitor-selected command."""
import os
import resource
import sys


def main():
    # Arguments are generated by ballot_intake, never copied from an upload.
    if len(sys.argv) != 3 or sys.argv[1] not in ('info', 'text'):
        return 126
    mode, tool = sys.argv[1:]
    expected = 'pdfinfo' if mode == 'info' else 'pdftotext'
    if not os.path.isabs(tool) or os.path.basename(tool) != expected:
        return 126
    try:
        resource.setrlimit(resource.RLIMIT_CPU, (5, 5))
        resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
        resource.setrlimit(resource.RLIMIT_FSIZE, (0, 0))
        resource.setrlimit(resource.RLIMIT_NOFILE, (32, 32))
        # Darwin rejects DATA and cannot use a useful AS limit with its loader.
        # The parent requires kernel RSS observation and kills above 256 MiB.
        if sys.platform != 'darwin':
            resource.setrlimit(resource.RLIMIT_DATA, (256 * 1024**2, 256 * 1024**2))
            resource.setrlimit(resource.RLIMIT_AS, (1024 * 1024**2, 1024 * 1024**2))
        args = [tool, '-enc', 'UTF-8', '-'] if mode == 'info' else [tool, '-layout', '-enc', 'UTF-8', '-eol', 'unix', '-', '-']
        os.execve(tool, args, dict(os.environ))
    except (OSError, ValueError):
        return 126


if __name__ == '__main__':
    sys.exit(main())
